+
+		const cards = page.getByTestId('plan-card');
+		const count = await cards.count();
+		expect(count).toBeGreaterThan(0);
+
+		// Each card should have a title and status badge
+		for (let i = 0; i < count; i++) {
+			const card = cards.nth(i);
