131		// Handle escape key
132		function handleKeydown(e: KeyboardEvent) {
133			if (e.key === 'Escape' && panel.open) {
134				handleCloseDetail();
135			}
136		}
137	
138		async function handleStartTask() {
139			if (!panel.task) return;
140	
141			// AC: @gh-pages-export ac-16, ac-18 - Check static mode
142			if (isStaticMode()) {
143				panelError = 'Cannot start task in read-only mode. Use the kspec CLI.';
144				return;
145			}
146	
147			isSubmitting = true;
148			panelError = '';
149	
150			try {
151				await startTask(panel.task._ulid);
152				// Reload task to get updated status
153				const updated = await fetchTask(panel.task._ulid);
154				panel.task = updated;
155				loadTasks();
156			} catch (err) {
157				// AC: @gh-pages-export ac-18 - Graceful error message
158				if (err instanceof ReadOnlyModeError) {
159					panelError = err.message;
160				} else {
161					panelError = err instanceof Error ? err.message : 'Failed to start task';
162				}
163			} finally {
164				isSubmitting = false;
165			}
166		}
167	
168		async function handleAddNote() {
169			if (!panel.task || !noteContent.trim()) return;
170	
171			// AC: @gh-pages-export ac-18 - Check static mode
172			if (isStaticMode()) {
173				panelError = 'Cannot add notes in read-only mode. Use the kspec CLI.';
174				return;
175			}
176	
177			isSubmitting = true;
178			panelError = '';
179	
180			try {
181				await addTaskNote(panel.task._ulid, noteContent);
182				noteContent = '';
183				// Reload task to get updated notes
184				const updated = await fetchTask(panel.task._ulid);
185				panel.task = updated;
186				loadTasks();
187			} catch (err) {
188				// AC: @gh-pages-export ac-18 - Graceful error message
189				if (err instanceof ReadOnlyModeError) {
190					panelError = err.message;
191				} else {
192					panelError = err instanceof Error ? err.message : 'Failed to add note';
193				}
194			} finally {
195				isSubmitting = false;
196			}
197		}
