199		function formatDate(dateStr: string): string {
200			const date = new Date(dateStr);
201			return new Intl.DateTimeFormat('en-US', {
202				year: 'numeric',
203				month: 'short',
204				day: 'numeric',
205				hour: '2-digit',
206				minute: '2-digit'
207			}).format(date);
208		}
209	
210		function getStatusColor(status: string): string {
211			const colors: Record<string, string> = {
212				pending: 'bg-gray-500',
213				in_progress: 'bg-blue-500',
214				pending_review: 'bg-yellow-500',
215				blocked: 'bg-red-500',
216				completed: 'bg-green-500',
217				cancelled: 'bg-gray-400'
218			};
219			return colors[status] || 'bg-gray-500';
220		}
221	
222		function formatStatus(status: string): string {
223			const labels: Record<string, string> = {
224				pending: 'Pending',
225				in_progress: 'In Progress',
226				pending_review: 'Pending Review',
227				blocked: 'Blocked',
228				completed: 'Completed',
229				cancelled: 'Cancelled'
230			};
231			return labels[status] || status;
232		}
233	
234		// AC: @web-dashboard ac-33 - Handle WebSocket task updates
235		function handleTaskUpdate(event: BroadcastEvent) {
236			console.log('[TasksPage] Task update received:', event);
237	
238			// Mark task as updated for highlight animation
239			if (event.data?.ulid) {
240				updatedTaskIds.add(event.data.ulid);
241				updatedTaskIds = new Set(updatedTaskIds);
242	
243				// Remove highlight after 3s
244				setTimeout(() => {
245					updatedTaskIds.delete(event.data.ulid);
246					updatedTaskIds = new Set(updatedTaskIds);
247				}, 3000);
248			}
249	
250			// Reload tasks list
251			loadTasks();
252	
253			// Reload selected task if it's the one that updated
254			if (panel.task && event.data?.ulid === panel.task._ulid) {
255				fetchTask(panel.task._ulid)
256					.then((updated) => {
257						panel.task = updated;
258					})
259					.catch((err) => {
260						console.error('Error reloading task:', err);
261					});
262			}
263		}
264	
265		onMount(() => {
266			loadTasks();
267	
268			// AC: @web-dashboard ac-32, ac-33 - Subscribe to task updates
